<?php
if (!defined('ABSPATH')) exit;
function cad_add_meta_boxes(){add_meta_box('cad-car-details','Vehicle Details','cad_car_box','cad_car','normal');add_meta_box('cad-transaction-details','Sale & Paperwork','cad_transaction_box','cad_transaction','normal');}
add_action('add_meta_boxes','cad_add_meta_boxes');
function cad_car_box($post){wp_nonce_field('cad_save_car','cad_car_nonce');$f=cad_car_fields($post->ID);foreach(['price','year','mileage','fuel','transmission','stock'] as $key){printf('<p><label><strong>%s</strong><br><input class="widefat" name="cad_%s" value="%s"></label></p>',esc_html(ucfirst($key)),$key,esc_attr($f[$key]));}echo '<p>Use the featured image for the main photo and the editor for specifications.</p>';}
function cad_transaction_box($post){wp_nonce_field('cad_save_transaction','cad_transaction_nonce');$user=get_post_meta($post->ID,'_cad_customer',true);$car=get_post_meta($post->ID,'_cad_car',true);$amount=get_post_meta($post->ID,'_cad_amount',true);$invoice=get_post_meta($post->ID,'_cad_invoice',true);$warranty=get_post_meta($post->ID,'_cad_warranty',true);printf('<p>Customer user ID<br><input class="widefat" name="cad_customer" value="%s"></p><p>Car post ID<br><input class="widefat" name="cad_car" value="%s"></p><p>Sale amount<br><input class="widefat" name="cad_amount" value="%s"></p><p>Invoice file URL<br><input class="widefat" name="cad_invoice" type="url" value="%s"></p><p>Warranty file URL<br><input class="widefat" name="cad_warranty" type="url" value="%s"></p>',$user,$car,$amount,$invoice,$warranty);}
function cad_save_meta($post_id){if(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)return;if(!current_user_can('edit_post',$post_id))return;if(isset($_POST['cad_car_nonce'])&&wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cad_car_nonce'])),'cad_save_car'))foreach(['price','year','mileage','fuel','transmission','stock'] as $k)if(isset($_POST['cad_'.$k]))update_post_meta($post_id,'_cad_'.$k,sanitize_text_field(wp_unslash($_POST['cad_'.$k])));if(isset($_POST['cad_transaction_nonce'])&&wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cad_transaction_nonce'])),'cad_save_transaction'))foreach(['customer','car','amount','invoice','warranty'] as $k)if(isset($_POST['cad_'.$k]))update_post_meta($post_id,'_cad_'.$k,sanitize_text_field(wp_unslash($_POST['cad_'.$k])));}
add_action('save_post','cad_save_meta');
